package com.bank.risk.model;

import java.math.BigDecimal;

// AMBER: sealed + records. VALHALLA (future): these could be `value record`s,
// so arrays of positions flatten into contiguous memory with no boxing.
public sealed interface Position permits EquityPosition, FxPosition {
    String id();
    BigDecimal notional();
}

record EquityPosition(String id, String symbol, long qty, BigDecimal price) implements Position {
    public BigDecimal notional() { return price.multiply(BigDecimal.valueOf(qty)); }
}
record FxPosition(String id, String pair, BigDecimal amount, BigDecimal rate) implements Position {
    public BigDecimal notional() { return amount.multiply(rate); }
}
