package com.bank.risk.service;

import com.bank.risk.model.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class ValuationService {
    private static final Logger log = Logger.getLogger(ValuationService.class.getName());

    // LOOM: simple blocking code, virtual thread per request → scales to 100k.
    // No reactive framework needed. This is the first compounding win.
    public Map<String, BigDecimal> valueConcurrently(List<Position> positions) throws InterruptedException {
        var results = new ConcurrentHashMap<String, BigDecimal>();
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (Position p : positions) {
                executor.submit(() -> results.put(p.id(), value(p)));
            }
        }
        return results;
    }

    // AMBER: exhaustive pattern-matching switch over the sealed type.
    private BigDecimal value(Position p) {
        BigDecimal base = switch (p) {
            case EquityPosition e -> e.notional();
            case FxPosition f     -> f.notional();
        };
        // PANAMA (future): a Monte-Carlo risk loop here would use the Vector API
        // for SIMD across scenarios, and the Foreign Function API to call a native
        // analytics library safely (no JNI). VALHALLA (future): value-type math
        // avoids boxing in that loop. Together = fast + simple + native-capable.
        return base.setScale(2, java.math.RoundingMode.HALF_UP);
    }
}
