package com.bank.risk;

import com.bank.risk.model.*;
import com.bank.risk.service.ValuationService;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ValuationDemo {
    private static final Logger log = Logger.getLogger(ValuationDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        List<Position> portfolio = List.of(
                new EquityPosition("POS-RAJESH-1", "RELIANCE", 100, new BigDecimal("2450.00")),
                new FxPosition("POS-PRIYA-1", "USDINR", new BigDecimal("10000.00"), new BigDecimal("83.10"))
        );
        var service = new ValuationService();
        Map<String, BigDecimal> valued = service.valueConcurrently(portfolio);
        valued.forEach((id, v) -> log.info(() -> "Valued " + id + " = Rs." + v));
        // LEYDEN (future): AOT + CDS → this serverless valuation starts in a few ms.
        log.info("One simple design: concurrent (Loom), expressive (Amber), "
                + "and ready for flat data (Valhalla) + SIMD/native (Panama) + fast start (Leyden)");
    }
}
